/**
 * Parallax Occlusion Mapping (POM) node for high-quality surface displacement.
 *
 * **Algorithm**
 * - Ray-marches through displacement texture along view direction
 * - Adaptive sampling: more samples at grazing angles
 * - Binary search refinement for sub-texel precision
 * - Blue noise jittering to eliminate banding artifacts
 * - Edge fading prevents UV stretching at borders
 * - Computes depth offset for correct depth buffer integration
 *
 * **Benefits**
 * - Creates deep surface detail without tessellation
 * - Accurate self-shadowing and occlusion
 * - Smooth interpolation via binary refinement
 * - Perceptually uniform with blue noise sampling
 * - Automatic LOD via adaptive sample count
 *
 * ```js
 * import { parallaxOcclusion } from '@three-blocks/core';
 * import { texture, uv } from 'three/tsl';
 *
 * const material = new MeshStandardNodeMaterial();
 * const heightMap = texture(heightTexture);
 * const blueNoise = texture(blueNoiseTexture);
 *
 * // Apply POM to displace UVs
 * const result = parallaxOcclusion(
 *   uv(),
 *   heightMap,
 *   0.08,        // parallax depth scale
 *   blueNoise,   // optional noise for quality
 *   32,          // min samples
 *   128,         // max samples
 *   4            // refinement steps
 * );
 *
 * // Use displaced UVs for texture sampling
 * material.colorNode = texture(diffuseTex, result.xy);
 * material.normalNode = normalMap(texture(normalTex, result.xy));
 * ```
 *
 * @function parallaxOcclusion
 * @short Parallax occlusion mapping node with adaptive raymarching and refinement; returns displaced UVs and depth offset.
 * @category TSL
 * @tags WebGPU, WebGL
 * @tsl
 * @param {Node.<vec2>} v_uv UV coordinates node.
 * @param {Node.<Texture>} dispTex Displacement/height map texture (white=raised, black=recessed).
 * @param {Node.<float>} [parallaxScale=0.05] Scale factor controlling depth of parallax effect.
 * @param {Node.<Texture>|null} [blueNoiseTex=null] Optional blue noise texture for jitter (reduces banding).
 * @param {Node.<int>} [minSamples=24] Minimum ray-march samples (used at perpendicular view).
 * @param {Node.<int>} [maxSamples=96] Maximum ray-march samples (used at grazing angles).
 * @param {Node.<int>} [refineSteps=3] Binary search refinement iterations for precision.
 * @param {Node.<float>} [edgeMargin=0.02] UV margin for edge fade (prevents stretching).
 * @returns {Node.<vec3>} Displaced UV coordinates (xy) and depth pixel offset (z).
 * @see {@link https://web.archive.org/web/20150419215321/http://sunandblackcat.com/tipFullView.php?l=eng&topicid=28}
 * @see {@link https://learnopengl.com/Advanced-Lighting/Parallax-Mapping}
 */
export const parallaxOcclusion: any;
